query.sql:
SELECT w.id AS worker_id, w.name AS worker_name, 'Director' AS role, g.genre_name AS genre, COUNT(DISTINCT wo.movie_id) AS movie_count FROM worker w JOIN worksOn wo ON w.worker_id = wo.worker_id AND wo.job = 'Director' JOIN movie_genre mg -- 'has' in ER ON wo.movie_id = mg.movie_id JOIN genre g ON mg.genre_id = genre.genre_id GROUP BY w.worker_id, w.worker_name, g.genre_id, g.genre_name
UNION ALL
SELECT w.id AS worker_id, w.name AS worker_name, 'Actor' AS role, g.genre_name AS genre, COUNT(DISTINCT pi.movie_id) AS movie_count FROM worker w JOIN playsIn pi ON w.worker_id = pi.worker_id JOIN movie_genre mg -- 'has' in ER ON pi.movie_id = mg.movie_id JOIN genre g ON mg.genre_id = genre.genre_id GROUP BY w.worker_id, w.worker_name, g.genre_id, g.genre_name ;

SELECT W.id AS worker_id, CASE WHEN W.role IS NULL THEN 'Actor' ELSE W.role END AS worker_role, AVG(R.rating) AS avg_rating FROM ( SELECT movie_id, rating FROM rated ) AS R JOIN ( ( SELECT id, movie_id, NULL FROM playsIn )
UNION
( SELECT id, movie_id, department AS role FROM worksOn )
) AS W ON R.movie_id = W.movie_id GROUP BY worker_role, worker_id HAVING avg_rating >= ? AND avg_rating <= ? ORDER BY avg_rating ? ;
